const H0 = this.helpers;
const BASE = 'https://atendimento.netliss.com', APP = '845ea1e5-1514-4185-ba04-aaad318d36c4';
const seg = n => { const i = $('Segredos').all().find(x => x.json.chave === n); return i ? String(i.json.valor || '') : ''; };
const espera = ms => new Promise(r => setTimeout(r, ms));
// tenta de novo se o DNS/rede falhar por um instante (ex.: EAI_AGAIN)
const req = async (o) => { let ult; for (let t = 1; t <= 4; t++) { try { return await H0.httpRequest(Object.assign({ json: true, timeout: 30000, returnFullResponse: true, ignoreHttpStatusErrors: true }, o)); } catch (e) { ult = e; await espera(5000 * t); } } throw ult; };
// 1) entra no Dify (aceita token no corpo ou nos cookies, conforme a versao)
let hdr = {};
for (const senha of [seg('dify_senha'), Buffer.from(seg('dify_senha')).toString('base64')]) {
  const r = await req({ method: 'POST', url: BASE + '/console/api/login', body: { email: seg('dify_usuario'), password: senha, remember_me: true }, headers: { 'Content-Type': 'application/json' } });
  let sc = r.headers['set-cookie'] || []; if (!Array.isArray(sc)) sc = [sc];
  const ck = sc.map(c => String(c).split(';')[0]);
  const tok = r.body && r.body.data && (r.body.data.access_token || (typeof r.body.data === 'string' ? r.body.data : ''));
  const csrf = (ck.find(c => /csrf_token=/.test(c)) || '').split('=').slice(1).join('=');
  if (r.statusCode < 300 && (tok || ck.length)) { hdr = Object.assign({}, tok ? { Authorization: 'Bearer ' + tok } : {}, ck.length ? { Cookie: ck.join('; ') } : {}, csrf ? { 'X-CSRF-Token': decodeURIComponent(csrf) } : {}); break; }
}
if (!Object.keys(hdr).length) return [{ json: { erro: 'nao consegui entrar no Dify com o usuario e a senha da tabela segredos', conversas: [] } }];
const PARES = [["CHAMADOS (abrir_chamado): a válvula de escape, não a saída fácil", "QUANDO UMA FERRAMENTA FALHA (vale para todas)\nSe uma ferramenta voltar com ok=false, success=false, erro ou sem resposta, quase sempre foi uma falha de um instante. Chame a MESMA ferramenta de novo, na hora, com os mesmos dados, até 03 vezes no total, sem escrever nada ao cliente entre as tentativas. Na grande maioria das vezes a segunda já dá certo e o cliente nem percebe.\nSó depois de 03 falhas seguidas fale com o cliente, e aí siga o que estas instruções mandam para aquele caso. Nunca fale em \"instabilidade\", \"erro\", \"sistema fora\" ou chamado antes de tentar as 03 vezes.\nExceção: quando a resposta da ferramenta disser um motivo que depende do cliente (ex.: limite de testes, usuário não encontrado, e-mail digitado errado), não repita: siga a orientação daquele caso.\n\nCHAMADOS (abrir_chamado): a válvula de escape, não a saída fácil"], ["- Falha ao gerar: diga que houve uma instabilidade e peça para tentar de novo em alguns minutos.", "- Falha ao gerar: tente de novo (veja QUANDO UMA FERRAMENTA FALHA). Só se as 03 tentativas falharem, diga que houve uma instabilidade e peça para tentar de novo em alguns minutos."], ["- ok=false (ou erro): peça desculpas pela instabilidade, diga que vai registrar o pedido", "- ok=false (ou erro): tente de novo (veja QUANDO UMA FERRAMENTA FALHA). Só se as 03 tentativas falharem: peça desculpas pela instabilidade, diga que vai registrar o pedido"], ["- PEDIDO quando gerar_cobranca falhar, ou proposta", "- PEDIDO quando gerar_cobranca falhar 03 vezes seguidas, ou proposta"]];
const aplicar = String($('W').first().json.query.aplicar || '') === '1';
const g = await req({ method: 'GET', url: BASE + '/console/api/apps/' + APP, headers: hdr });
if (g.statusCode >= 300) return [{ json: { erro: 'GET app ' + g.statusCode } }];
const mc = g.body.model_config; let pp = String(mc.pre_prompt || ''); const cont = [];
for (const [a, b] of PARES) { const n = pp.split(a).length - 1; cont.push(n); if (n === 1) pp = pp.replace(a, b); }
const tudoOk = cont.every(n => n === 1);
let post = null;
if (aplicar && tudoOk) {
  const corpo = Object.assign({}, mc, { pre_prompt: pp }); delete corpo.created_at; delete corpo.updated_at; delete corpo.created_by; delete corpo.updated_by;
  const p = await req({ method: 'POST', url: BASE + '/console/api/apps/' + APP + '/model-config', body: corpo, headers: Object.assign({ 'Content-Type': 'application/json' }, hdr) });
  const g2 = await req({ method: 'GET', url: BASE + '/console/api/apps/' + APP, headers: hdr });
  const novo = String(g2.body.model_config.pre_prompt || '');
  post = { status: p.statusCode, corpo: JSON.stringify(p.body).slice(0, 200), confere: novo === pp, tem_bloco: novo.includes('QUANDO UMA FERRAMENTA FALHA'), modelo: g2.body.model_config.model && g2.body.model_config.model.name, params: JSON.stringify((g2.body.model_config.model || {}).completion_params || {}).slice(0, 300), ferramentas: ((g2.body.model_config.agent_mode || {}).tools || []).length };
}
return [{ json: { cont, tudoOk, tamanho: pp.length, ferramentas_antes: ((mc.agent_mode || {}).tools || []).length, post } }];
